class TestSlidingWindow:
    """Verify exact boundary semantics of the sliding window algorithm."""

    def test_accepts_requests_within_limit(self, limiter_custom):
        """Should accept requests up to the configured limit."""
        for _ in range(3):
            assert limiter_custom.check("agent_a") is True

    def test_rejects_requests_over_limit(self, limiter_custom):
        """Should reject requests exceeding the limit."""
        for _ in range(3):
            limiter_custom.check("agent_a")
        with pytest.raises(RateLimitExceeded):
            limiter_custom.check("agent_a")

    def test_window_slides_after_expiry(self, limiter_custom):
        """After window expiry, requests should be accepted again."""
        for _ in range(3):
            limiter_custom.check("agent_a")

        # Simulate window expiry
        limiter_custom._windows["agent_a"].append(
            datetime.now() - timedelta(seconds=limiter_custom.default_window + 1)
        )

        # Prune expired entries
        limiter_custom._prune("agent_a")

        # Should accept new requests
        assert limiter_custom.check("agent_a") is True

    def test_exact_boundary_acceptance(self, limiter_custom):
        """Request at exact window boundary should be accepted."""
        for _ in range(3):
            limiter_custom.check("agent_a")

        # Manually set timestamps to exact boundary
        now = datetime.now()
        boundary = now - timedelta(seconds=limiter_custom.default_window)
        limiter_custom._windows["agent_a"] = deque([boundary] * 3)

        # Prune should remove entries exactly at boundary
        limiter_custom._prune("agent_a")
        assert len(limiter_custom._windows["agent_a"]) == 0

    def test_window_pruning_removes_only_expired(self, limiter_custom):
        """Pruning should remove only expired entries, keeping recent ones."""
        now = datetime.now()
        limiter_custom._windows["agent_a"] = deque([
            now - timedelta(seconds=1),   # recent
            now - timedelta(seconds=3),   # expired
            now - timedelta(seconds=0.5), # recent
        ])

        limiter_custom._prune("agent_a")

        assert len(limiter_custom._windows["agent_a"]) == 2


