class TestRateLimitExceeded:
    """Verify exception payload contains actionable information."""

    def test_exception_contains_retry_after(self, limiter_custom):
        """Exception should include retry_after timestamp."""
        for _ in range(3):
            limiter_custom.check("agent_a")

        with pytest.raises(RateLimitExceeded) as exc_info:
            limiter_custom.check("agent_a")

