class TestThreadSafety:
    """Verify thread-safe behavior under concurrent access."""

    def test_concurrent_requests_same_agent(self, limiter_custom):
        """Concurrent requests from same agent should not exceed limit."""
        errors = []
        results = []
        lock = threading.Lock()

        def worker():
            try:
                result = limiter_custom.check("agent_shared")
                with lock:
                    results.append(result)
            except RateLimitExceeded:
                with lock:
                    results.append(False)

        threads = [threading.Thread(target=worker) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # At most 3 should succeed
        successes = sum(1 for r in results if r is True)
        assert successes <= 3

    def test_concurrent_requests_different_agents(self, limiter_custom):
        """Concurrent requests from different agents should all succeed."""
        results = []
        lock = threading.Lock()

        def worker(agent_id):
            try:
                result = limiter_custom.check(agent_id)
                with lock:
                    results.append(result)
            except RateLimitExceeded:
                with lock:
                    results.append(False)

        threads = [
            threading.Thread(target=worker, args=(f"agent_{i}",))
            for i in range(10)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert all(results)  # All should succeed

    def test_stress_thread_safety(self, limiter_custom):
        """Stress test: 100 threads, 100 iterations each."""
        limiter_custom = RateLimiter(default_limit=1000, default_window=60)
        errors = []
        lock = threading.Lock()

        def worker():
            try:
                for _ in range(100):
                    limiter_custom.check("stress_agent")
            except RateLimitExceeded:
                with lock:
                    errors.append(1)

        threads = [threading.Thread(target=worker) for _ in range(100)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors  # No rate limit errors under 1000 limit

    def test_thread_safety_with_mixed_operations(self, limiter_custom):
        """Concurrent check and prune operations should not corrupt state."""
        limiter_custom = RateLimiter(default_limit=100, default_window=1)
        errors = []

        def checker():
            try:
                for _ in range(50):
                    limiter_custom.check("mixed_agent")
                    time.sleep(0.001)
            except RateLimitExceeded:
                pass  # Expected under tight window
            except Exception as e:
                errors.append(e)

        def pruner():
            try:
                for _ in range(50):
                    limiter_custom._prune("mixed_agent")
                    time.sleep(0.001)
            except Exception as e:
                errors.append(e)

        threads = [
            threading.Thread(target=checker),
            threading.Thread(target=pruner),
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors  # No unexpected exceptions


