class TestPropertyBased:
    """Property-based tests using Hypothesis."""

    @given(st.lists(st.text(), min_size=0, max_size=50))
    @settings(max_examples=100)
    def test_counter_accuracy(self, agent_ids):
        """Counter should never exceed limit for any agent."""
        limiter = RateLimiter(default_limit=10, default_window=60)
        counts = {}

        for agent_id in agent_ids:
            try:
                limiter.check(agent_id)
                counts[agent_id] = counts.get(agent_id, 0) + 1
            except RateLimitExceeded:
                pass

        # Verify no agent exceeded the limit
        for agent_id, count in counts.items():
            assert count <= 10

    @given(st.integers(min_value=1, max_value=100))
    @settings(max_examples=50)
    def test_window_pruning_correctness(self, window_size):
        """Pruning should correctly remove expired entries."""
        limiter = RateLimiter(default_limit=100, default_window=window_size)
        now = datetime.now()

        # Create entries with mixed ages
        entries = deque()
        for i in range(50):
            age = i % (window_size + 5)  # Mix of expired and recent
            entries.append(now - timedelta(seconds=age))

        limiter._windows["test_agent"] = entries
        limiter._prune("test_agent")

        # All remaining entries should be within window
        for entry in limiter._windows["test_agent"]:
            age = (now - entry).total_seconds()
            assert age <= window_size

    @given(st.integers(min_value=1, max_value=50), st.integers(min_value=1, max_value=10))
    @settings(max_examples=50)
    def test_limit_enforcement(self, limit, window):
        """Rate limiter should enforce limits across random configurations."""
        limiter = RateLimiter(default_limit=limit, default_window=window)
        successes = 0

        for _ in range(limit * 2):
            try:
                limiter.check("property_agent")
                successes += 1
            except RateLimitExceeded:
                break

        assert successes <= limit

    @given(st.lists(st.integers(min_value=0, max_value=100), min_size=0, max_size=20))
    @settings(max_examples=50)
    def test_agent_isolation_property(self, agent_ids):
        """Agent isolation should hold for arbitrary agent sets."""
        limiter = RateLimiter(default_limit=5, default_window=60)
        agent_limits = {}

        for agent_id in agent_ids:
            agent_key = f"agent_{agent_id}"
            try:
                limiter.check(agent_key)
                agent_limits[agent_key] = agent_limits.get(agent_key, 0) + 1
            except RateLimitExceeded:
                pass

        # Each agent's count should be independent
        for agent_key, count in agent_limits.items():
            assert count <= 5


