class TestIntegration:
    """End-to-end integration scenarios."""

    def test_full_lifecycle(self, limiter_custom):
        """Complete lifecycle: accept, exhaust, wait, accept again."""
        # Phase 1: Accept up to limit
        for _ in range(3):
            assert limiter_custom.check("lifecycle_agent") is True

        # Phase 2: Reject over limit
        with pytest.raises(RateLimitExceeded):
            limiter_custom.check("lifecycle_agent")

        # Phase 3: Wait for window expiry
        time.sleep(2.1)

        # Phase 4: Accept again
        assert limiter_custom.check("lifecycle_agent") is True

    def test_mixed_agent_workload(self, limiter_custom):
        """Mixed workload with multiple agents and varying request rates."""
        import random

        agents = [f"worker_{i}" for i in range(5)]

        for _ in range(20):
            agent = random.choice(agents)
            try:
                limiter_custom.check(agent)
            except RateLimitExceeded:
                pass  # Expected for some agents

        # Verify no agent exceeded limit
        for agent in agents:
            count = len(limiter_custom._windows.get(agent, []))
            assert count <= 3

    def test_concurrent_mixed_agents(self, limiter_custom):
        """Concurrent requests from mixed agents with rate limiting."""
        results = []
        lock = threading.Lock()

        def worker(agent_id, iterations):
            local_results = []
            for _ in range(iterations):
                try:
                    limiter_custom.check(agent_id)
                    local_results.append(True)
                except RateLimitExceeded:
                    local_results.append(False)
            with lock:
                results.extend(local_results)

        threads = [
            threading.Thread(target=worker, args=(f"agent_{i}", 5))
            for i in range(4)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # Each agent should have at most 3 successes
        for i in range(4):
            agent_results = [r for r in results if r]
            assert len(agent_results) <= 12  # 4 agents * 3 limit


